import mq3.client.ui_player_settings as p
import mq3.client.ui_players as players
import mq3.client.ui_qmenu as menu
function req(value,message) if not value then return error(7893,message) end if;return 1 end function
function main(args)
  count=0;files=[];for each name in p.artList() files=files+[name] end for;source=players.assetSource(files,[],true);s=p.create(source);p.UI_PlayerSettingsMenu(s,"^1Ranger",4,"sarge/default",75,true);count=count+req(s.pushed and len(s.menu.items)==10,"menu lifecycle");count=count+req(len(s.assets)==14 and len(s.actions)==15 and not s.actions[0].dispatched,"retail cache suppression");count=count+req(s.name.buffer=="^1Ranger" and s.handicap==5 and s.effects==0,"cvar mapping");rows=p.PlayerSettings_DrawName(s,false,true);count=count+req(rows[len(rows)-1].text=="Ranger","clean player name");rows=p.PlayerSettings_DrawEffects(s,true,true);count=count+req(rows[2].asset=="menu/art/fx_red" and rows[2].x==264,"effects marker");rows=p.PlayerSettings_DrawHandicap(s,false,true);count=count+req(rows[1].text=="75","handicap label");p.PlayerSettings_SaveChanges(s,true);count=count+req(s.cvarWrites[0][1]=="^1Ranger" and s.cvarWrites[1][1]=="75" and s.cvarWrites[2][1]=="4","save semantics");before=len(s.cvarWrites);p.PlayerSettings_MenuEvent(s,p.ID_MODEL,menu.QM_ACTIVATED,true);count=count+req(s.modelMenu and len(s.cvarWrites)==before+3,"model transition saves");p.PlayerSettings_MenuEvent(s,p.ID_BACK,menu.QM_ACTIVATED,true);count=count+req(s.popped,"back transition");print("PASS: "+str(count)+" native ui_player_settings contracts");return 0
end function
